import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const jsonType = 'application/json; charset=utf-8';

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': jsonType });
  res.end(JSON.stringify(body));
}

function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  const detail: Record<string, unknown> = { code, message };
  if (fields) detail.fields = fields;
  send(res, status, { error: detail });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.setEncoding('utf8');
    req.on('data', (chunk: string) => {
      body += chunk;
      if (body.length > 1_000_000) reject(new Error('body too large'));
    });
    req.on('end', () => resolve(body));
    req.on('error', reject);
  });
}

function getJob(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const heartbeat = db.prepare('SELECT updated_at FROM worker_heartbeat WHERE id = 1').get() as { updated_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - heartbeat.updated_at < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    const key = req.headers['idempotency-key'];
    if (Array.isArray(key) || (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key))) {
      fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, digits, underscores, or hyphens.' });
    }
    const idempotencyKey = typeof key === 'string' ? key : undefined;

    let parsed: unknown;
    try { parsed = JSON.parse(await readBody(req)); }
    catch { parsed = undefined; fields.push({ field: 'body', message: 'Body must be valid JSON.' }); }
    const obj = typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed) ? parsed as Record<string, unknown> : undefined;
    if (parsed !== undefined && !obj) fields.push({ field: 'body', message: 'Body must be a JSON object.' });

    let input = '';
    let steps = 5;
    let failAttempts = 0;
    if (obj) {
      for (const field of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(field)) fields.push({ field, message: 'Unknown field.' });
      if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'Required.' });
      else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
      else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must be 1–1000 characters and not only whitespace.' });
      else input = obj.input;
      if (Object.hasOwn(obj, 'steps')) {
        if (typeof obj.steps !== 'number' || !Number.isInteger(obj.steps) || obj.steps < 1 || obj.steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
        else steps = obj.steps;
      }
      if (Object.hasOwn(obj, 'failAttempts')) {
        if (typeof obj.failAttempts !== 'number' || !Number.isInteger(obj.failAttempts) || obj.failAttempts < 0 || obj.failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
        else failAttempts = obj.failAttempts;
      }
    }
    if (fields.length) return error(res, 400, 'invalid_request', 'The request is invalid.', fields);

    const payload = JSON.stringify({ input, steps, failAttempts });
    if (idempotencyKey) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as (JobRow & { payload: string }) | undefined;
      if (existing) {
        if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return send(res, 200, toJob(existing));
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    try {
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,idempotency_key,payload,available_at)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, 0)`)
        .run(id, input, steps, failAttempts, now, now, idempotencyKey ?? null, payload);
    } catch (e) {
      // A concurrent request may have inserted this key after the lookup above.
      if (idempotencyKey) {
        const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as (JobRow & { payload: string }) | undefined;
        if (existing) {
          if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          return send(res, 200, toJob(existing));
        }
      }
      throw e;
    }
    const created = getJob(id);
    return send(res, 201, toJob(created!));
  }
  if (pathname === '/api/jobs') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = getJob(decodeURIComponent(match[1]!));
    return row ? send(res, 200, toJob(row)) : error(res, 404, 'not_found', 'Job not found.');
  }
  if (pathname.startsWith('/api/jobs/') || pathname === '/api/jobs') return error(res, 404, 'not_found', 'Not found.');
  return error(res, 404, 'not_found', 'Not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
let active = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => { stopping = true; });
}

// A running row has no live owner after this process starts: requeue it for recovery.
const stamp = new Date().toISOString();
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=0 WHERE status='running'").run(stamp);

function heartbeat(): void {
  db.prepare(`INSERT INTO worker_heartbeat(id,updated_at) VALUES(1,?)
    ON CONFLICT(id) DO UPDATE SET updated_at=excluded.updated_at`).run(Date.now());
}

function claim(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as JobRow | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now, row.id);
    db.exec('COMMIT');
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0, updated_at: now };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function processJob(row: JobRow): Promise<void> {
  active = true;
  try {
    if (row.attempts <= row.fail_attempts) {
      // Simulated dependency failure occurs before any step is recorded.
      if (row.attempts >= 3) {
        db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), row.id);
      } else {
        db.prepare("UPDATE jobs SET status='queued', error=NULL, result_output=NULL, progress_completed=0, available_at=?, updated_at=? WHERE id=? AND status='running'")
          .run(Date.now() + 500, new Date().toISOString(), row.id);
      }
      return;
    }

    for (let completed = 1; completed <= row.steps; completed++) {
      await sleep(100);
      if (stopping) return; // leave running state for recovery at the next worker start
      db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'")
        .run(completed, new Date().toISOString(), row.id);
    }
    db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'")
      .run(row.input.toUpperCase(), new Date().toISOString(), row.id);
  } finally {
    active = false;
  }
}

console.log('worker started');
heartbeat();
while (!stopping) {
  heartbeat();
  const job = claim();
  if (job) await processJob(job);
  else await sleep(100);
}
if (!active) {
  // Marking this worker stale lets health report down immediately after a clean stop.
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
}
db.close();
